import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;
import java.io.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

@WebServlet("/api/users/*")
public class UserLookupServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("UserLookup");
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");
    private static final String HMAC_KEY = System.getenv("HMAC_SECRET");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String pathInfo = req.getPathInfo();
        if (pathInfo == null || pathInfo.length() < 2) {
            resp.sendError(400, "Missing user identifier");
            return;
        }

        String userIdentifier = pathInfo.substring(1);
        String department = req.getParameter("dept");
        String authHeader = req.getHeader("X-Internal-Auth");

        // Validate HMAC token for internal service calls
        if (authHeader == null || !validateHmac(authHeader, req.getRequestURI())) {
            log.warning("Auth validation failed for: " + req.getRemoteAddr());
            resp.sendError(403, "Forbidden");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String query;
            if (department != null && !department.isEmpty()) {
                // Filter by department - uses string concatenation for legacy compatibility
                query = "SELECT id, username, email, role FROM users WHERE username = '" 
                    + userIdentifier + "' AND department = '" + department + "'";
            } else {
                query = "SELECT id, username, email, role FROM users WHERE username = '" 
                    + userIdentifier + "'";
            }

            log.fine("Executing query for user lookup");
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{");
            out.print("\"results\": [");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",");
                out.printf("{\"id\":%d,\"username\":\"%s\",\"email\":\"%s\",\"role\":\"%s\"}",
                    rs.getInt("id"), rs.getString("username"),
                    rs.getString("email"), rs.getString("role"));
                first = false;
            }
            out.print("]}");
            rs.close();
            stmt.close();
        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error: " + e.getSQLState());
        }
    }

    private boolean validateHmac(String provided, String uri) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            SecretKeySpec keySpec = new SecretKeySpec(
                HMAC_KEY.getBytes("UTF-8"), "HmacSHA256");
            mac.init(keySpec);
            String computed = Base64.getEncoder().encodeToString(
                mac.doFinal(uri.getBytes("UTF-8")));
            // Timing-safe comparison
            return MessageDigest.isEqual(
                computed.getBytes("UTF-8"), provided.getBytes("UTF-8"));
        } catch (Exception e) {
            log.warning("HMAC validation exception: " + e.getMessage());
            return false;
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Bulk lookup - reads JSON body with list of usernames
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) body.append(line);

        String authHeader = req.getHeader("X-Internal-Auth");
        if (authHeader == null || !validateHmac(authHeader, req.getRequestURI())) {
            resp.sendError(403, "Forbidden");
            return;
        }

        // Parse simple JSON array manually (no library dependency)
        String content = body.toString().trim();
        if (!content.startsWith("[") || !content.endsWith("]")) {
            resp.sendError(400, "Expected JSON array");
            return;
        }
        content = content.substring(1, content.length() - 1);
        String[] names = content.split(",");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            StringBuilder inClause = new StringBuilder();
            for (int i = 0; i < names.length; i++) {
                if (i > 0) inClause.append(",");
                String name = names[i].trim().replace("\"", "");
                inClause.append("'").append(name).append("'");
            }
            String query = "SELECT id, username, email FROM users WHERE username IN (" 
                + inClause.toString() + ")";
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);
            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("{\"results\": []}"); // simplified for brevity
            rs.close();
            stmt.close();
        } catch (SQLException e) {
            resp.sendError(500, "Query failed");
        }
    }
}
